// Package appicon embeds Cad-lite's application icon as the PNG set the window icon is made of.
// The files are generated by `just appicon` from appicon.svg; see README.md.
package appicon

import (
	"bytes"
	"embed"
	"image"
	"image/png"
	"sort"
)

//go:embed window-*.png
var files embed.FS

// Images returns the window icon at 16, 32, 48, 64, 128 and 256 px, smallest first, for
// ebiten.SetWindowIcon. A file that fails to decode is skipped, so the result may be shorter
// but never contains nil.
func Images() []image.Image {
	entries, err := files.ReadDir(".")
	if err != nil {
		return nil
	}
	type sized struct {
		w   int
		img image.Image
	}
	var all []sized
	for _, e := range entries {
		b, err := files.ReadFile(e.Name())
		if err != nil {
			continue
		}
		img, err := png.Decode(bytes.NewReader(b))
		if err != nil {
			continue
		}
		all = append(all, sized{img.Bounds().Dx(), img})
	}
	sort.Slice(all, func(i, j int) bool { return all[i].w < all[j].w })
	out := make([]image.Image, len(all))
	for i, s := range all {
		out[i] = s.img
	}
	return out
}

// Image returns the window icon whose edge is px, or the nearest size when the set has none that
// exact, and nil if the set is empty. The UI uses it to draw the logo 1:1 on the device grid.
func Image(px int) image.Image {
	var best image.Image
	bestD := -1
	for _, img := range Images() {
		d := img.Bounds().Dx() - px
		if d < 0 {
			d = -d
		}
		if bestD < 0 || d < bestD {
			best, bestD = img, d
		}
	}
	return best
}
